"""Version the inline modules generated by wasm-bindgen for static hosting."""
import argparse
import hashlib
from pathlib import Path
import re


def version_imports(package):
    wrapper = package / 'zed_browser_probe.js'
    imports = re.compile(r'^(import[^\n]+ from [\'\"])(\./snippets/[^\'\"?\n]+)(?:\?v=[a-f0-9]+)?([\'\"])', re.MULTILINE)

    def version(match):
        prefix, path, quote = match.groups()
        digest = hashlib.sha256((package / path).read_bytes()).hexdigest()[:12]
        return f'{prefix}{path}?v={digest}{quote}'

    changed, count = imports.subn(version, wrapper.read_text())
    if not count:
        raise ValueError('No wasm-bindgen snippet imports were found')
    wrapper.write_text(changed)


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('package', type=Path)
    version_imports(parser.parse_args().package)
